// Common pass: Shared musical score, chromatic patterns, and pitch utilities
// Sergei Rachmaninoff's Piano arrangement of "Flight of the Bumblebee" (Complete 104 Measures)

#define BPM 180.0
#define TOTAL_MEASURES 104
#define TOTAL_DURATION (104.0 * (2.0 / 3.0))

bool isBlackKey(int midi) {
    int n = midi % 12;
    return (n == 1 || n == 3 || n == 6 || n == 8 || n == 10);
}

float midiToFreq(float note) {
    return 440.0 * exp2((note - 69.0) / 12.0);
}

// 8-note chromatic patterns (each measure = 8 sixteenth notes in 2/4 time)
float getPatternNote(int patternId, int idx) {
    if (patternId == 0) {
        int p[8] = int[8](71, 70, 69, 68, 69, 70, 71, 72);
        return float(p[idx]);
    } else if (patternId == 1) {
        int p[8] = int[8](73, 74, 75, 76, 77, 76, 75, 74);
        return float(p[idx]);
    } else if (patternId == 2) {
        int p[8] = int[8](73, 72, 71, 70, 69, 68, 69, 70);
        return float(p[idx]);
    } else if (patternId == 3) {
        int p[8] = int[8](71, 72, 73, 74, 75, 76, 77, 78);
        return float(p[idx]);
    } else if (patternId == 4) {
        int p[8] = int[8](79, 78, 77, 76, 75, 74, 73, 72);
        return float(p[idx]);
    } else if (patternId == 5) {
        int p[8] = int[8](71, 70, 69, 68, 67, 66, 65, 64);
        return float(p[idx]);
    } else if (patternId == 6) {
        int p[8] = int[8](63, 64, 65, 66, 67, 68, 69, 70);
        return float(p[idx]);
    } else if (patternId == 7) {
        int p[8] = int[8](77, 76, 75, 74, 73, 74, 75, 76);
        return float(p[idx]);
    } else if (patternId == 8) {
        int p[8] = int[8](83, 82, 81, 80, 81, 82, 83, 84);
        return float(p[idx]);
    } else if (patternId == 9) {
        int p[8] = int[8](85, 86, 87, 88, 89, 88, 87, 86);
        return float(p[idx]);
    } else if (patternId == 10) {
        int p[8] = int[8](85, 84, 83, 82, 81, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 11) {
        int p[8] = int[8](83, 84, 85, 86, 87, 88, 89, 90);
        return float(p[idx]);
    } else if (patternId == 12) {
        int p[8] = int[8](91, 90, 89, 88, 87, 86, 85, 84);
        return float(p[idx]);
    } else if (patternId == 13) {
        int p[8] = int[8](83, 82, 81, 80, 79, 78, 77, 76);
        return float(p[idx]);
    } else if (patternId == 14) {
        int p[8] = int[8](75, 76, 77, 78, 79, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 15) {
        int p[8] = int[8](75, 74, 73, 72, 71, 70, 69, 68);
        return float(p[idx]);
    } else if (patternId == 16) {
        int p[8] = int[8](67, 66, 65, 64, 63, 62, 61, 60);
        return float(p[idx]);
    } else if (patternId == 17) {
        int p[8] = int[8](59, 60, 61, 62, 63, 64, 65, 66);
        return float(p[idx]);
    } else if (patternId == 18) {
        int p[8] = int[8](67, 68, 69, 70, 71, 72, 73, 74);
        return float(p[idx]);
    } else if (patternId == 19) {
        int p[8] = int[8](75, 76, 77, 78, 79, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 20) {
        int p[8] = int[8](83, 84, 85, 86, 87, 88, 89, 90);
        return float(p[idx]);
    } else {
        int p[8] = int[8](83, 82, 81, 80, 81, 81, 81, 81);
        return float(p[idx]);
    }
}

float getLHInversionPattern(int patternId, int idx) {
    if (patternId == 0) {
        int p[8] = int[8](40, 41, 42, 43, 44, 45, 46, 47);
        return float(p[idx]);
    } else if (patternId == 1) {
        int p[8] = int[8](48, 47, 46, 45, 44, 45, 46, 47);
        return float(p[idx]);
    } else if (patternId == 2) {
        int p[8] = int[8](48, 49, 50, 51, 52, 53, 54, 55);
        return float(p[idx]);
    } else {
        int p[8] = int[8](56, 55, 54, 53, 52, 51, 50, 49);
        return float(p[idx]);
    }
}

int getMeasurePatternId(int m) {
    if (m < 8) {
        int pat[8] = int[8](0, 1, 2, 3, 4, 5, 6, 3);
        return pat[m];
    } else if (m < 16) {
        int pat[8] = int[8](0, 1, 2, 3, 4, 5, 6, 3);
        return pat[m - 8];
    } else if (m < 24) {
        int pat[8] = int[8](0, 1, 7, 2, 3, 4, 5, 6);
        return pat[m - 16];
    } else if (m < 32) {
        if (m < 28) return 0;
        int pat[4] = int[4](1, 2, 3, 4);
        return pat[m - 28];
    } else if (m < 40) {
        if (m < 36) return 0;
        int pat[4] = int[4](4, 5, 6, 3);
        return pat[m - 36];
    } else if (m < 52) {
        int pat[12] = int[12](7, 4, 4, 4, 4, 1, 2, 3, 4, 5, 6, 3);
        return pat[m - 40];
    } else if (m < 64) {
        if (m < 60) return 0;
        int pat[4] = int[4](6, 3, 0, 1);
        return pat[m - 60];
    } else if (m < 72) {
        int pat[8] = int[8](1, 2, 3, 4, 5, 6, 0, 1);
        return pat[m - 64];
    } else if (m < 80) {
        int pat[8] = int[8](2, 3, 4, 5, 6, 3, 0, 1);
        return pat[m - 72];
    } else if (m < 84) {
        int pat[4] = int[4](2, 3, 4, 14);
        return pat[m - 80];
    } else if (m < 92) {
        int pat[8] = int[8](8, 9, 10, 11, 12, 13, 14, 11);
        return pat[m - 84];
    } else if (m < 100) {
        int pat[8] = int[8](12, 13, 15, 16, 17, 18, 19, 20);
        return pat[m - 92];
    } else {
        int pat[4] = int[4](12, 21, 0, 0);
        return pat[m - 100];
    }
}

float getActiveScoreNote(int measure, int stepInMeasure) {
    if (measure >= 52 && measure < 60) {
        return getLHInversionPattern((measure - 52) % 4, stepInMeasure);
    } else if ((measure >= 24 && measure < 28) || (measure >= 32 && measure < 36)) {
        return (measure % 4 == 0) ? 81.0 : ((measure % 4 == 1) ? 83.0 : ((measure % 4 == 2) ? 81.0 : 86.0));
    } else {
        return getPatternNote(getMeasurePatternId(measure), stepInMeasure);
    }
}

// Concert Grand Piano - Visual Stage
// Real-time animated piano keyboard, vibrating gold strings, and Russian Imperial hall lighting
// Utilizing shared musical score functions from the Common pass

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);

    float pTime = mod(iTime, TOTAL_DURATION);
    int totalStep16 = int(floor(pTime * 12.0));
    int measure = totalStep16 / 8;
    int stepInMeasure = totalStep16 % 8;
    float tau16 = fract(pTime * 12.0);

    float activeMidi = getActiveScoreNote(measure, stepInMeasure);

    vec3 col = mix(vec3(0.06, 0.03, 0.02), vec3(0.012, 0.006, 0.004), length(uv) * 1.2);

    if (uv.y < 0.12 && uv.y > -0.52) {
        float pers = mix(1.15, 0.90, (uv.y + 0.5) / 0.62);
        float kx = (uv.x / pers) * 44.0 + 66.0;
        int keyMidi = int(floor(kx));
        float keyFract = fract(kx);

        bool black = isBlackKey(keyMidi);
        bool isPressed = (abs(float(keyMidi) - activeMidi) < 0.6);
        float keyY = (uv.y + 0.5) / 0.62;

        if (keyY > 0.40 && black) {
            vec3 ebony = vec3(0.05, 0.05, 0.05);
            if (isPressed) {
                ebony = mix(ebony, vec3(0.85, 0.55, 0.15), exp(-8.0 * tau16));
            }
            float edge = smoothstep(0.0, 0.1, keyFract) * (1.0 - smoothstep(0.9, 1.0, keyFract));
            ebony += vec3(0.18) * pow(edge, 4.0);
            col = ebony;
        } else {
            vec3 ivory = vec3(0.94, 0.92, 0.88);
            if (isPressed) {
                ivory = mix(ivory, vec3(1.0, 0.82, 0.45), exp(-6.0 * tau16) * 0.7);
            }
            float gap = smoothstep(0.0, 0.04, keyFract) * (1.0 - smoothstep(0.96, 1.0, keyFract));
            ivory *= mix(0.25, 1.0, gap);
            ivory *= mix(0.85, 1.05, keyY);
            col = ivory;
        }
    }
    else if (uv.y >= 0.12) {
        vec3 soundboard = vec3(0.18, 0.10, 0.04);
        float stringPattern = sin(uv.x * 240.0 + uv.y * 30.0);
        float vibration = sin(uv.y * 40.0 - iTime * 25.0) * exp(-4.0 * tau16);
        float stringBright = smoothstep(0.85, 1.0, stringPattern + vibration * 0.3);
        vec3 stringCol = vec3(0.95, 0.80, 0.35);
        col = mix(soundboard, stringCol, stringBright * 0.75);

        float strut = smoothstep(0.03, 0.0, abs(uv.x - 0.25 + uv.y * 0.3));
        col = mix(col, vec3(0.40, 0.28, 0.08), strut * 0.8);
    }

    for (int i = 0; i < 12; i++) {
        float fi = float(i);
        vec2 p = vec2(
            sin(fi * 1.3 + iTime * 0.4) * 0.6,
            cos(fi * 0.9 + iTime * 0.3) * 0.4
        );
        float d = length(uv - p);
        col += vec3(1.0, 0.85, 0.4) * (0.0006 / (d * d + 0.0004));
    }

    col *= 1.0 - 0.5 * dot(uv, uv);
    fragColor = vec4(col, 1.0);
}

// Physical-modeling concert grand piano synthesis on the GPU via PassType.sound
// Utilizing shared musical score functions from the Common pass

float pianoVoice(float freq, float tau, float noteDur, float velocity, bool isBass) {
    if (freq <= 0.0) return 0.0;
    float attack = smoothstep(0.0, 0.0012, tau);
    float decay = isBass ? (0.40 * exp(-5.5 * tau) + 0.60 * exp(-2.0 * tau))
                         : (0.45 * exp(-30.0 * tau) + 0.55 * exp(-7.0 * tau));
    float damper = isBass ? (1.0 - smoothstep(noteDur * 0.88, noteDur, tau))
                          : (1.0 - smoothstep(noteDur * 0.78, noteDur, tau));
    float env = attack * decay * damper;

    float detune = isBass ? 0.20 : 0.45;
    float p1 = 6.2831853 * freq * tau;
    float p2 = 6.2831853 * (freq + detune) * tau;
    float bright = pow(clamp(velocity, 0.5, 1.6), 1.3);

    float sig;
    if (isBass) {
        sig = 0.55 * sin(p1)
            + 0.85 * sin(2.0 * p1) * exp(-2.5 * tau)
            + 0.70 * sin(3.0 * p1) * exp(-4.5 * tau)
            + 0.50 * sin(4.0 * p1) * exp(-7.0 * tau) * bright
            + 0.32 * sin(5.0 * p1) * exp(-10.0 * tau) * bright;
    } else {
        sig = (0.52 * sin(p1) + 0.48 * sin(p2))
            + 0.65 * sin(2.0 * p1) * exp(-10.0 * tau) * bright
            + 0.42 * sin(3.0 * p1) * exp(-18.0 * tau) * bright
            + 0.26 * sin(4.0 * p1) * exp(-28.0 * tau) * bright
            + 0.15 * sin(5.0 * p1) * exp(-42.0 * tau) * bright;
    }

    float thumpF = isBass ? 75.0 : 130.0;
    float thump = sin(6.2831853 * thumpF * tau) * exp(-85.0 * tau) * (isBass ? 0.35 : 0.20);
    float bodyRes = 1.0 + 0.35 * exp(-pow((freq - 260.0) / 180.0, 2.0));
    return (sig + thump) * env * velocity * bodyRes * 0.22;
}

vec2 panStereo(float sig, float pan) {
    float angle = clamp(pan, 0.0, 1.0) * 1.5707963;
    return vec2(sig * cos(angle), sig * sin(angle));
}

vec2 mainSound( int samp, float time ) {
    float beatDur = 60.0 / BPM;
    float noteDur16 = beatDur / 4.0;
    float pTime = mod(time, TOTAL_DURATION);

    int totalStep16 = int(floor(pTime * 12.0));
    int measure = totalStep16 / 8;
    int stepInMeasure = totalStep16 % 8;
    float tau16 = fract(pTime * 12.0) * (1.0 / 12.0);

    int totalBeat = int(floor(pTime * 3.0));
    int beatInMeasure = totalBeat % 2;
    float tauBeat = fract(pTime * 3.0) * (1.0 / 3.0);

    vec2 outAudio = vec2(0.0);

    bool isLHInversion = (measure >= 52 && measure < 60);
    bool isCantabile = (measure >= 24 && measure < 28) || (measure >= 32 && measure < 36);

    if (isCantabile) {
        float cMelodyMidi = (measure % 4 == 0) ? 81.0 : ((measure % 4 == 1) ? 83.0 : ((measure % 4 == 2) ? 81.0 : 86.0));
        float c1 = pianoVoice(midiToFreq(cMelodyMidi), tauBeat, beatDur * 2.0, 1.30, false);
        float c2 = pianoVoice(midiToFreq(cMelodyMidi - 12.0), tauBeat, beatDur * 2.0, 1.10, false);
        outAudio += panStereo(c1 + c2, 0.65);

        float arpm = float(stepInMeasure % 4);
        float lhArpMidi = 45.0 + arpm * 7.0;
        float arpSound = pianoVoice(midiToFreq(lhArpMidi), tau16, noteDur16 * 2.0, 0.85, true);
        outAudio += panStereo(arpSound, 0.30);
    }
    else if (isLHInversion) {
        int lhPatId = (measure - 52) % 4;
        float lhMidi = getLHInversionPattern(lhPatId, stepInMeasure);
        float lhBuzz = pianoVoice(midiToFreq(lhMidi), tau16, noteDur16, 1.10, true);
        outAudio += panStereo(lhBuzz, 0.28);

        if (beatInMeasure == 1) {
            float chord1 = pianoVoice(midiToFreq(64.0), tauBeat, beatDur, 1.0, false); // E4
            float chord2 = pianoVoice(midiToFreq(69.0), tauBeat, beatDur, 1.0, false); // A4
            float chord3 = pianoVoice(midiToFreq(72.0), tauBeat, beatDur, 1.0, false); // C5
            outAudio += panStereo(chord1 + chord2 + chord3, 0.62);
        }
    }
    else {
        int patId = getMeasurePatternId(measure);
        float rhMidi = getPatternNote(patId, stepInMeasure);

        float vel = 1.0;
        if (measure < 4) vel = 1.25;
        else if (measure < 8) vel = mix(1.20, 0.70, float(measure - 4) / 4.0);
        else if (measure < 24) vel = 0.85;
        else if (measure >= 40 && measure < 52) vel = 1.25;
        else if (measure >= 64 && measure < 84) vel = 0.80;
        else if (measure >= 84 && measure < 100) vel = 1.15;
        else vel = mix(0.95, 0.40, float(measure - 100) / 4.0);

        float rhSound = pianoVoice(midiToFreq(rhMidi), tau16, noteDur16, vel, false);
        float rhPan = 0.48 + 0.24 * ((rhMidi - 60.0) / 30.0);
        outAudio += panStereo(rhSound, rhPan);

        if (measure >= 8 && measure < 102) {
            bool isDownbeat = (beatInMeasure == 0);
            if (isDownbeat) {
                float bMidi = (measure % 4 == 3) ? 40.0 : 45.0;
                float b1 = pianoVoice(midiToFreq(bMidi - 12.0), tauBeat, beatDur, 1.15, true);
                float b2 = pianoVoice(midiToFreq(bMidi), tauBeat, beatDur, 1.05, true);
                outAudio += panStereo(b1, 0.20) + panStereo(b2, 0.28);
            } else {
                float c1 = pianoVoice(midiToFreq(52.0), tauBeat, beatDur, 0.85, false);
                float c2 = pianoVoice(midiToFreq(57.0), tauBeat, beatDur, 0.80, false);
                float c3 = pianoVoice(midiToFreq(60.0), tauBeat, beatDur, 0.80, false);
                outAudio += panStereo(c1 + c2 + c3, 0.38);
            }
        }
    }

    if (measure == 102) {
        float f1 = pianoVoice(midiToFreq(21.0), tauBeat, beatDur * 4.0, 1.2, true);
        float f2 = pianoVoice(midiToFreq(33.0), tauBeat, beatDur * 4.0, 1.1, true);
        outAudio += panStereo(f1 + f2, 0.22);
    } else if (measure == 103 && beatInMeasure == 0) {
        float sBass = pianoVoice(midiToFreq(33.0), tauBeat, beatDur, 1.5, true);
        float sCh1 = pianoVoice(midiToFreq(69.0), tauBeat, beatDur, 1.4, false);
        float sCh2 = pianoVoice(midiToFreq(72.0), tauBeat, beatDur, 1.4, false);
        float sCh3 = pianoVoice(midiToFreq(76.0), tauBeat, beatDur, 1.4, false);
        float sCh4 = pianoVoice(midiToFreq(81.0), tauBeat, beatDur, 1.4, false);
        outAudio += panStereo(sBass, 0.25) + panStereo(sCh1 + sCh2 + sCh3 + sCh4, 0.60);
    }

    return clamp(outAudio, -0.95, 0.95);
}
